import{_ as t,o as a,c as o,a2 as n}from"./chunks/framework.l66uSLlc.js";const u=JSON.parse('{"title":"Using Noto","description":"","frontmatter":{},"headers":[],"relativePath":"guide/using.md","filePath":"guide/using.md","lastUpdated":1789542331000}'),i={name:"guide/using.md"};function s(r,e,d,h,c,l){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="using-noto" tabindex="-1">Using Noto <a class="header-anchor" href="#using-noto" aria-label="Permalink to &quot;Using Noto&quot;">​</a></h1><p>Open a file with <code>Cmd+O</code>, or open a folder with <code>Cmd+Alt+O</code> to get the workspace tree. Open notes sit behind a quiet Recent strip in the status bar rather than a classic tab bar. The rail on the left holds Files and Outline by default; Links (graph / related) stays off until you turn it on in Settings → Appearance. The one control at the top left opens and closes the rail, and <code>Cmd+Shift+L</code> and <code>Cmd+Shift+O</code> open it directly on the view they name. <code>Cmd+F</code> finds, <code>Cmd+Alt+F</code> finds and replaces, <code>Cmd+K</code> opens the command palette, and <code>Cmd+,</code> opens Settings (and closes it again) — a full-page shell with categories, where plugins are turned on under the Plugins section. On Windows and Linux, read Control for Command.</p><p>The title bar carries the filename and nothing else that is not an action you can take right now: Save appears when there is something to save and is absent when there is not. The gear is the single Settings entry; Plugins is reached from Settings&#39; left nav, not a second top-bar icon.</p><p>Settings carries the document&#39;s typography, so text size, line height and line width are yours to set rather than fixed: the width is a character count, not a pixel width, so it holds as the size changes. Saving automatically is there too, off by default and debounced against typing, and it refuses in exactly the cases the Save button refuses. A custom stylesheet can be pointed at any absolute path and wins over the built-in theme, so <code>:root { --accent: … }</code> is enough to retheme the app without editing it. See <a href="./theming">Theming</a>.</p><p><code>Cmd+P</code> is quick open: type part of a note&#39;s name or its path and it ranks the whole folder by how well it matches and by how often and how recently you open it, so an empty box already shows the few notes you probably want. <code>Enter</code> opens the note; <code>Alt+Enter</code> writes a <code>[[wiki link]]</code> to it at the caret instead. Wiki links render inline wherever they appear, and <code>Cmd+click</code> follows one.</p><p>The links are decorations rather than a node type, so they cannot reach the saved bytes: <code>[[a note]]</code> is ordinary text in the file, exactly as you typed it.</p><p><code>Cmd+Shift+F</code> searches inside the notes rather than across their names, and <code>Tab</code> switches between the two without leaving the box. A content result shows the lines it was found on, and opening one lands on the match with the find bar already carrying the query.</p><p>The open folder names itself on the tree&#39;s first row; an ellipsis on that row holds what acts on the folder: open another, reveal it in the file manager, refresh, and the folders you opened before. <code>Cmd+Shift+R</code> reveals the current note instead.</p><p><code>Cmd+/</code> opens Source Code Mode: the whole note as the Markdown it is saved as, the way Typora&#39;s Command-slash does. <code>Cmd+Alt+/</code> still toggles source for the single block under the caret, which is the escape hatch when you want to fix one paragraph, one table or one fence without leaving the rest rendered.</p><p>Markdown input rules work as you type: <code>#</code> for a heading, <code>-</code> for a list, <code>```</code> for a code fence. The syntax markers for the block you are editing appear while you are in it and fold away when you leave, so the document stays readable without hiding what it is made of.</p><h2 id="byte-exact-saving" tabindex="-1">Byte-exact saving <a class="header-anchor" href="#byte-exact-saving" aria-label="Permalink to &quot;Byte-exact saving&quot;">​</a></h2><p>This is the property the rest of the design is arranged around. Most editors that render Markdown round-trip it through a serializer, so opening and saving a file rewrites parts of it you never touched: a list marker changes, emphasis switches from <code>_</code> to <code>*</code>, a table&#39;s padding is normalized, trailing whitespace disappears.</p><p>Noto parses the file into blocks, records the exact source bytes of each one along with its origin and hash, and on save writes back the recorded bytes for every block that was not edited. Only blocks you actually changed are serialized. A document you open and save without touching is identical to the byte.</p><p>The same block record is what detects an external change: if the file on disk no longer matches what was accepted, the save is refused and you are offered a copy rather than an overwrite.</p>',14)])])}const f=t(i,[["render",s]]);export{u as __pageData,f as default};
